import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { JSX } from 'solid-js';
import { children as resolveChildren, splitProps } from 'solid-js';
import { CloseIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './CloseButton.module.css';

type CloseButtonRootProps = HTMLArkProps<'button'> & {
  'data-disabled'?: string;
  'data-part'?: string;
  'data-scope'?: string;
  'data-slot'?: string;
  onClickCapture?: (event: MouseEvent) => void;
};

const ArkButton = ark.button as (
  props: CloseButtonRootProps & {
    'oncapture:click'?: (event: MouseEvent) => void;
  },
) => JSX.Element;

function CloseButtonRoot(props: CloseButtonRootProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'aria-disabled',
    'aria-label',
    'aria-labelledby',
    'children',
    'class',
    'data-disabled',
    'data-part',
    'data-scope',
    'data-slot',
    'disabled',
    'onClick',
    'onClickCapture',
    'type',
  ]);
  const resolvedChildren = resolveChildren(() => local.children);
  const isDisabled = () =>
    local.disabled ||
    local['aria-disabled'] === true ||
    local['aria-disabled'] === 'true' ||
    local['data-disabled'] !== undefined;
  const handleClickCapture = (event: MouseEvent) => {
    if (isDisabled()) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    local.onClickCapture?.(event);
  };
  const handleClick = (event: MouseEvent) => {
    if (isDisabled()) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    (local.onClick as ((event: MouseEvent) => void) | undefined)?.(event);
  };

  return (
    <ArkButton
      asChild={local.asChild}
      {...others}
      type={local.asChild ? local.type : (local.type ?? 'button')}
      disabled={local.asChild ? undefined : local.disabled}
      data-scope={local['data-scope'] ?? 'close-button'}
      data-part={local['data-part'] ?? 'root'}
      data-slot={local['data-slot'] ?? 'close-button-root'}
      data-disabled={local['data-disabled'] ?? (isDisabled() ? '' : undefined)}
      class={clsx(styles.root, local.class)}
      aria-disabled={local.asChild && local.disabled ? true : local['aria-disabled']}
      aria-label={local['aria-label'] ?? (local['aria-labelledby'] == null ? 'Close' : undefined)}
      aria-labelledby={local['aria-labelledby']}
      oncapture:click={handleClickCapture}
      onClick={handleClick}
    >
      {local.asChild ? undefined : resolvedChildren() || <CloseIcon />}
    </ArkButton>
  );
}

const CloseButton = Object.assign(CloseButtonRoot, {
  Root: CloseButtonRoot,
});

export { CloseButton };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: var(--moduix-close-button-size, var(--moduix-spacing-7));
    height: var(--moduix-close-button-size, var(--moduix-spacing-7));
    margin: 0;
    padding: 0;
    border: none;
    background-color: var(--moduix-close-button-bg, transparent);
    border-radius: var(--moduix-close-button-radius, var(--moduix-radius-sm));
    color: var(--moduix-close-button-color, var(--moduix-color-muted-foreground));
    appearance: none;
    font: inherit;
    user-select: none;
    cursor: pointer;
    transition:
      background-color var(--moduix-close-button-transition, var(--moduix-transition-default)),
      color var(--moduix-close-button-transition, var(--moduix-transition-default)),
      opacity var(--moduix-close-button-transition, var(--moduix-transition-default)),
      translate var(--moduix-close-button-transition, var(--moduix-transition-default)),
      scale var(--moduix-close-button-transition, var(--moduix-transition-default));

    & > svg {
      flex-shrink: 0;
      width: var(--moduix-close-button-icon-size, var(--moduix-spacing-3));
      height: var(--moduix-close-button-icon-size, var(--moduix-spacing-3));
    }

    @media (hover: hover) {
      &:hover:not([data-disabled]) {
        background-color: var(--moduix-close-button-bg-hover, var(--moduix-color-muted));
        color: var(--moduix-close-button-color-hover, var(--moduix-color-foreground));
      }
    }

    &:focus-visible {
      outline: var(
          --moduix-close-button-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-close-button-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-close-button-focus-ring-offset, var(--moduix-focus-ring-offset));
    }

    &:active:not([data-disabled]) {
      opacity: 0.94;
    }

    @media (prefers-reduced-motion: no-preference) {
      &:active:not([data-disabled]) {
        translate: 0 1px;
        scale: 0.985;
      }
    }

    &[data-disabled] {
      cursor: default;
      pointer-events: none;
      opacity: var(--moduix-close-button-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }
}
